namespace kvhttp {

// Owns a file descriptor and closes it on destruction.
class UniqueFd {
public:
    UniqueFd() noexcept = default;
    explicit UniqueFd(int fd) noexcept : fd_(fd) {}
    UniqueFd(UniqueFd&& other) noexcept : fd_(std::exchange(other.fd_, -1)) {}
    UniqueFd& operator=(UniqueFd&& other) noexcept {
        if (this != &other) reset(std::exchange(other.fd_, -1));
        return *this;
    }
    UniqueFd(const UniqueFd&) = delete;
    UniqueFd& operator=(const UniqueFd&) = delete;
    ~UniqueFd() { reset(); }

    [[nodiscard]] int get() const noexcept { return fd_; }
    [[nodiscard]] explicit operator bool() const noexcept { return fd_ >= 0; }
    void reset(int fd = -1) noexcept;

private:
    int fd_ = -1;
};

struct ServerOptions {
    std::uint16_t port = 0;
    std::size_t worker_count = 128;
    int idle_timeout_seconds = 10;
};

// Blocking HTTP/1.1 server: one accept loop feeding a fixed pool of connection workers.
class Server {
public:
    Server(ServerOptions options, const Router& router);

    // Accepts connections forever (until the process is terminated).
    [[noreturn]] void run();

private:
    void worker_loop(std::stop_token stop);
    void serve_connection(const UniqueFd& client) const;

    ServerOptions options_;
    const Router& router_;
    UniqueFd listener_;

    std::mutex mutex_;
    std::condition_variable_any ready_;
    std::deque<UniqueFd> pending_;
    std::vector<std::jthread> workers_;  // last member: joined before the rest is destroyed
};

}  // namespace kvhttp

#include "store.hpp"

#include <mutex>
#include <utility>

namespace kvhttp {

KvStore::PutResult KvStore::put(std::string key, std::string value) {
    std::unique_lock lock(mutex_);
    auto [it, inserted] = data_.try_emplace(std::move(key), std::move(value));
    if (inserted) return PutResult::Created;
    it->second = std::move(value);  // try_emplace leaves `value` untouched on failure
    return PutResult::Replaced;
}

std::optional<std::string> KvStore::get(std::string_view key) const {
    std::shared_lock lock(mutex_);
    if (auto it = data_.find(key); it != data_.end()) return it->second;
    return std::nullopt;
}

bool KvStore::erase(std::string_view key) {
    std::unique_lock lock(mutex_);
    auto it = data_.find(key);
    if (it == data_.end()) return false;
    data_.erase(it);
    return true;
}

std::vector<std::string> KvStore::keys() const {
    std::shared_lock lock(mutex_);
    std::vector<std::string> result;
    result.reserve(data_.size());
    for (const auto& [key, value] : data_) result.push_back(key);
    return result;
}

}  // namespace kvhttp

